-- Dedicated filtered/media adapters. No provider execution or verification occurs.
-- Ciphertext/opaque tokens are private, short lived and never customer credentials.
BEGIN;
CREATE TABLE public.sandy_provider_supplement_opaque (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 actor_id uuid NOT NULL, source_admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id),
 operation text NOT NULL, registry_revision_sha256 text NOT NULL, scope_sha256 text NOT NULL,
 source_input_sha256 text NOT NULL, binding_sha256 text NOT NULL, target text NOT NULL,
 kind text NOT NULL CHECK(kind IN ('cursor','artifact','redirect')),
 vault_secret_id uuid NOT NULL UNIQUE, payload_sha256 text NOT NULL CHECK(payload_sha256 ~ '^[a-f0-9]{64}$'),
 byte_length integer NOT NULL CHECK(byte_length BETWEEN 0 AND 1048576), media_type text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL,
 consumed_by uuid REFERENCES public.sandy_api_execution_admissions(id), consumed_at timestamptz,
 CHECK(expires_at > created_at AND expires_at <= created_at + interval '10 minutes'),
 CHECK((consumed_at IS NULL)=(consumed_by IS NULL))
);
ALTER TABLE public.sandy_provider_supplement_opaque ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_provider_supplement_opaque FROM PUBLIC,anon,authenticated,service_role;
CREATE INDEX sandy_provider_supplement_opaque_expiry ON public.sandy_provider_supplement_opaque(expires_at);
CREATE FUNCTION public.sandy_provider_supplement_context(p_context jsonb)
RETURNS public.sandy_api_execution_admissions LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions; entry public.sandy_operation_registry; target text;
BEGIN
 IF jsonb_typeof(p_context) IS DISTINCT FROM 'object'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_context) key WHERE key NOT IN
 ('actor','admission','operation','scope_sha256','input_sha256','binding_sha256','target','kind','payload_base64','payload_sha256','byte_length','media_type'))
 OR p_context->>'actor' IS NULL OR p_context->>'admission' IS NULL
 OR p_context->>'operation' !~ '^(gcp|supabase|github)\.[a-z][a-z0-9_.-]{1,95}$'
 OR p_context->>'scope_sha256' !~ '^[a-f0-9]{64}$' OR p_context->>'input_sha256' !~ '^[a-f0-9]{64}$'
 OR p_context->>'binding_sha256' !~ '^[a-f0-9]{64}$'
 OR p_context->>'kind' NOT IN ('cursor','artifact','redirect') THEN RAISE EXCEPTION 'supplement_context_invalid'; END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=(p_context->>'admission')::uuid FOR SHARE;
 IF admission.id IS NULL OR admission.actor_id IS DISTINCT FROM (p_context->>'actor')::uuid
 OR admission.tenant_id IS NOT NULL OR admission.credential_id IS NOT NULL OR admission.approval_id IS NULL
 OR admission.operation IS DISTINCT FROM p_context->>'operation' OR admission.state IS DISTINCT FROM 'consumed'
 OR admission.scope_sha256 IS DISTINCT FROM p_context->>'scope_sha256' OR admission.input_sha256 IS DISTINCT FROM p_context->>'input_sha256'
 OR admission.expires_at<=clock_timestamp() OR NOT public.sandy_api_current_owner(admission.actor_id)
 THEN RAISE EXCEPTION 'supplement_consumed_owner_admission_required'; END IF;
 SELECT * INTO entry FROM public.sandy_operation_registry WHERE operation=admission.operation FOR SHARE;
 IF entry.handler IS DISTINCT FROM 'sandy-provider-supplement-api' OR entry.api_exposed IS DISTINCT FROM true OR entry.verified IS DISTINCT FROM true
 OR entry.error_contract->>'requires_approval' IS DISTINCT FROM 'true' OR entry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false'
 OR entry.error_contract->>'requires_grant' IS DISTINCT FROM 'true' OR entry.permission_scope IS DISTINCT FROM 'infrastructure:write'
 OR entry.is_mutation IS DISTINCT FROM admission.is_mutation
 OR public.sandy_api_registry_revision(admission.operation) IS DISTINCT FROM admission.registry_revision_sha256
 THEN RAISE EXCEPTION 'supplement_current_verified_contract_required'; END IF;
 target:=p_context->>'target';
 IF target IS NULL OR octet_length(target)>3000 OR target ~ '[[:cntrl:]]' OR target ~ '(%0[aAdD]|[[:space:]#])'
 OR (CASE
 WHEN admission.operation LIKE 'supabase.functions.%' THEN target !~ '^https://api\.supabase\.com/v1/projects/zmqlyygzqoidkcwdysok/functions/[a-z][a-z0-9-]{0,62}/body$'
 WHEN admission.operation LIKE 'github.%' THEN target !~ '^https://api\.github\.com/repos/ausstyle/web-staging/actions/(jobs|runs|artifacts)/[0-9]+/'
 WHEN admission.operation='gcp.organizations.search_filtered' THEN target !~ '^https://cloudresourcemanager\.googleapis\.com/v3/organizations:search\?pageSize=[0-9]+$'
 WHEN admission.operation='gcp.folders.search_filtered' THEN target !~ '^https://cloudresourcemanager\.googleapis\.com/v3/folders:search\?query=state%3DACTIVE&pageSize=[0-9]+$'
 WHEN admission.operation='gcp.projects.search_filtered' THEN target !~ '^https://cloudresourcemanager\.googleapis\.com/v3/projects:search\?query=projectId%3Aelaborate-haven-511518-a5&pageSize=[0-9]+$'
 WHEN admission.operation='gcp.projects.list_filtered' THEN target !~ '^https://cloudresourcemanager\.googleapis\.com/v3/projects\?parent=(folders|organizations)%2F[0-9]+&pageSize=[0-9]+$'
 WHEN admission.operation='gcp.billing.accounts.list_filtered' THEN target !~ '^https://cloudbilling\.googleapis\.com/v1/billingAccounts\?pageSize=[0-9]+$'
 WHEN admission.operation='gcp.load_balancers.backends.effective_security_policies.capture' THEN target !~ '^https://compute\.googleapis\.com/compute/v1/projects/elaborate-haven-511518-a5/global/backendServices/[a-z][a-z0-9-]{0,62}/getEffectiveSecurityPolicies$'
 WHEN admission.operation='gcp.artifacts.files.download.capture' THEN target !~ '^https://artifactregistry\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/repositories/[a-z][a-z0-9-]{0,62}/files/[^?#]+:download\?alt=media$'
 ELSE true END) THEN RAISE EXCEPTION 'supplement_fixed_resource_required'; END IF;
 IF (p_context->>'kind'='cursor') IS DISTINCT FROM (admission.operation IN ('gcp.organizations.search_filtered','gcp.folders.search_filtered','gcp.projects.list_filtered','gcp.projects.search_filtered','gcp.billing.accounts.list_filtered'))
 OR p_context->>'kind'='redirect' AND admission.operation NOT LIKE 'github.actions.%'
 THEN RAISE EXCEPTION 'supplement_payload_kind_refused'; END IF;
 RETURN admission;
END $$;
CREATE FUNCTION public.sandy_provider_supplement_cleanup_opaque() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item record; removed integer:=0;
BEGIN
 FOR item IN SELECT id,vault_secret_id FROM public.sandy_provider_supplement_opaque
  WHERE expires_at<=clock_timestamp() OR consumed_at IS NOT NULL ORDER BY expires_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP
  DELETE FROM public.sandy_provider_supplement_opaque WHERE id=item.id;
  DELETE FROM vault.secrets WHERE id=item.vault_secret_id;
  removed:=removed+1;
 END LOOP;
 RETURN removed;
END $$;
CREATE FUNCTION public.sandy_provider_supplement_save_opaque(p_context jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions; payload bytea; secret uuid; receipt public.sandy_provider_supplement_opaque;
BEGIN
 admission:=public.sandy_provider_supplement_context(p_context);
 IF p_context->>'payload_base64' IS NULL OR octet_length(p_context->>'payload_base64')>1398104
 OR p_context->>'payload_base64' !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$'
 OR p_context->>'payload_sha256' !~ '^[a-f0-9]{64}$' OR p_context->>'media_type' IS NULL
 OR p_context->>'media_type' !~ '^[A-Za-z0-9!#$&^_.+-]+/[A-Za-z0-9!#$&^_.+-]+$' OR octet_length(p_context->>'media_type')>100
 OR jsonb_typeof(p_context->'byte_length') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'supplement_payload_invalid'; END IF;
 payload:=decode(p_context->>'payload_base64','base64');
 IF octet_length(payload)>1048576 OR octet_length(payload) IS DISTINCT FROM (p_context->>'byte_length')::integer
 OR replace(encode(payload,'base64'),E'\n','') IS DISTINCT FROM p_context->>'payload_base64'
 OR encode(extensions.digest(payload,'sha256'),'hex') IS DISTINCT FROM p_context->>'payload_sha256'
 OR p_context->>'kind' IN ('cursor','redirect') AND octet_length(payload) NOT BETWEEN 1 AND 8192
 THEN RAISE EXCEPTION 'supplement_payload_integrity_failed'; END IF;
 PERFORM public.sandy_provider_supplement_cleanup_opaque();
 -- A consumed exact admission has one immutable custody result; a retry cannot
 -- create a second object or substitute different response material.
 IF EXISTS(SELECT 1 FROM public.sandy_provider_supplement_opaque WHERE source_admission_id=admission.id)
 THEN RAISE EXCEPTION 'supplement_admission_already_captured'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sandy_provider_supplement_quota',0));
 IF (SELECT count(*) FROM public.sandy_provider_supplement_opaque WHERE actor_id=admission.actor_id)>=32
 OR (SELECT coalesce(sum(byte_length),0) FROM public.sandy_provider_supplement_opaque)+octet_length(payload)>67108864
 THEN RAISE EXCEPTION 'supplement_private_custody_quota_reached'; END IF;
 secret:=vault.create_secret(p_context->>'payload_base64','SANDY_PROVIDER_MEDIA_'||gen_random_uuid()::text,'Private short-lived provider media/cursor; never return material');
 INSERT INTO public.sandy_provider_supplement_opaque(actor_id,source_admission_id,operation,registry_revision_sha256,scope_sha256,
 source_input_sha256,binding_sha256,target,kind,vault_secret_id,payload_sha256,byte_length,media_type,expires_at)
 VALUES(admission.actor_id,admission.id,admission.operation,admission.registry_revision_sha256,admission.scope_sha256,
 admission.input_sha256,p_context->>'binding_sha256',p_context->>'target',p_context->>'kind',secret,p_context->>'payload_sha256',
 octet_length(payload),p_context->>'media_type',clock_timestamp()+CASE WHEN p_context->>'kind'='artifact' THEN interval '10 minutes' ELSE interval '5 minutes' END)
 RETURNING * INTO receipt;
 RETURN jsonb_build_object('custody_id',receipt.id,'byte_length',receipt.byte_length,'sha256',receipt.payload_sha256,
  'media_type',receipt.media_type,'expires_at',receipt.expires_at);
END $$;
CREATE FUNCTION public.sandy_provider_supplement_take_opaque(p_context jsonb,p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions; saved public.sandy_provider_supplement_opaque; material text; payload bytea;
BEGIN
 admission:=public.sandy_provider_supplement_context(p_context);
 SELECT * INTO saved FROM public.sandy_provider_supplement_opaque WHERE id=p_id FOR UPDATE;
 IF saved.id IS NULL OR saved.source_admission_id=admission.id OR saved.actor_id IS DISTINCT FROM admission.actor_id OR saved.operation IS DISTINCT FROM admission.operation
 OR saved.scope_sha256 IS DISTINCT FROM admission.scope_sha256 OR saved.registry_revision_sha256 IS DISTINCT FROM admission.registry_revision_sha256
 OR saved.binding_sha256 IS DISTINCT FROM p_context->>'binding_sha256' OR saved.target IS DISTINCT FROM p_context->>'target'
 OR saved.kind IS DISTINCT FROM p_context->>'kind' OR saved.kind IS DISTINCT FROM 'cursor'
 OR saved.expires_at<=clock_timestamp() OR saved.consumed_at IS NOT NULL
 THEN RAISE EXCEPTION 'supplement_opaque_binding_expired_or_used'; END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=saved.vault_secret_id;
 IF material IS NULL OR octet_length(material)>1398104 THEN RAISE EXCEPTION 'supplement_opaque_integrity_failed'; END IF;
 payload:=decode(material,'base64');
 IF octet_length(payload) IS DISTINCT FROM saved.byte_length OR encode(extensions.digest(payload,'sha256'),'hex') IS DISTINCT FROM saved.payload_sha256
 THEN RAISE EXCEPTION 'supplement_opaque_integrity_failed'; END IF;
 UPDATE public.sandy_provider_supplement_opaque SET consumed_at=clock_timestamp(),consumed_by=admission.id WHERE id=saved.id;
 RETURN jsonb_build_object('payload_base64',material,'sha256',saved.payload_sha256,'byte_length',saved.byte_length);
END $$;
REVOKE ALL ON FUNCTION public.sandy_provider_supplement_context(jsonb),public.sandy_provider_supplement_cleanup_opaque(),
 public.sandy_provider_supplement_save_opaque(jsonb),public.sandy_provider_supplement_take_opaque(jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_provider_supplement_cleanup_opaque(),public.sandy_provider_supplement_save_opaque(jsonb),
 public.sandy_provider_supplement_take_opaque(jsonb,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.sandy_provider_supplement_context(jsonb) FROM service_role;
DO $expiry$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_extension WHERE extname='pg_cron') THEN
  IF EXISTS(SELECT 1 FROM cron.job WHERE jobname='sandy-provider-supplement-expiry') THEN
   RAISE EXCEPTION 'supplement_expiry_job_name_already_used';
  END IF;
  PERFORM cron.schedule('sandy-provider-supplement-expiry','* * * * *','SELECT public.sandy_provider_supplement_cleanup_opaque()');
 END IF;
END $expiry$;
-- GENERATED_CONSUMER_AND_REGISTRY
DO $consumer$
DECLARE original text; updated text;
BEGIN
 SELECT prosrc INTO original FROM pg_proc WHERE oid='public.sandy_credential_resolve_consumer(text,uuid,uuid,text)'::regprocedure AND prosecdef;
 IF encode(extensions.digest(original,'sha256'),'hex') IS DISTINCT FROM 'ff5e15282be44ce823b77e71d477dc3be74bb93c58a7ded1d279e0f2bdd3999c' THEN RAISE EXCEPTION 'reviewed08300_consumer_required'; END IF;
 updated:=replace(original,'''sandy-provider-read-api'',''sandy-provider-gap-api'')','''sandy-provider-read-api'',''sandy-provider-gap-api'',''sandy-provider-supplement-api'')');
 IF updated IS NOT DISTINCT FROM original THEN RAISE EXCEPTION 'consumer_allowlist_replacement_failed'; END IF;
 EXECUTE 'CREATE OR REPLACE FUNCTION public.sandy_credential_resolve_consumer(p_consumer text,p_actor uuid,p_admission uuid,p_operation text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '||quote_literal(updated);
END $consumer$;
REVOKE ALL ON FUNCTION public.sandy_credential_resolve_consumer(text,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_credential_resolve_consumer(text,uuid,uuid,text) TO service_role;
